"""Авторские пошаговые схемы: фиксированные состояния, без сети и исполнения API."""
def step(title, text, actor, focus, active, states, name, before, after, why):
    return dict(title=title, explanation=text, actor=actor, focus=focus, active=active,
                states=states, fields=[dict(name=name, before=before, after=after, why=why)],
                bands=[dict(label=name, value=after, detail=why)])

def diagram(identity, chapter, title, intro, assumptions, marker, nodes, edges, steps):
    return dict(id=identity, volume='artifactory', chapter=chapter, anchor=chapter,
                title=title, intro=intro, assumptions=assumptions, insert_before=marker,
                nodes=[dict(id=i, label=l, sub=s) for i,l,s in nodes],
                edges=[dict(id=i, **{'from':a, 'to':b}, label=l) for i,a,b,l in edges], steps=steps)

